// Generated by Cypress Author on 2026-10-22
//
// SUI 07 (P1, servidor) — Plano_de_Testes_QA_MatchWallet.md §9.1 (docs-test/areas/sui.md).
// Interrupção e reenvio: sem conclusão não existe avaliação gravada, e reenviar as mesmas respostas
// (retry depois de perder a resposta) não pode criar uma segunda avaliação. Contas DESCARTÁVEIS.
//
// ATENÇÃO — o segundo teste deve FALHAR: `POST /suitability/avaliar` não é idempotente; cada
// chamada cria uma avaliação nova (e fecha/abre um vínculo). Um retry após timeout vira avaliação
// duplicada no histórico. Corrigir exige uma chave de idempotência ou regra de "mesmas respostas
// em curto intervalo"; a decisão é de produto.

function historico(usuarioId: string) {
  return cy
    .apiRequest<Array<{ id: string; pontuacaoTotal: number; perfilResultante: string }>>({
      method: 'GET',
      url: `/usuarios/${usuarioId}/historico-suitability`,
    })
    .its('body')
}

function comoAdmin() {
  cy.clearCookies()
  cy.loginReal('admin')
}

describe('Plano QA · Suitability · interrupção e reenvio (servidor)', () => {
  it('SUI 07 · cliente abre o questionário e abandona → nenhuma avaliação, perfil ou vínculo gravados', () => {
    cy.criarUsuarioDescartavel().then((conta) => {
      cy.loginComo(conta)
      // "Meio do questionário": só leu as perguntas.
      cy.apiRequest({ method: 'GET', url: '/suitability/perguntas' })
        .its('status')
        .should('eq', 200)

      cy.apiRequest<{ perfilInvestidor: string | null; carteiraVinculada: unknown }>({
        method: 'GET',
        url: '/auth/me',
      }).then(({ body }) => {
        expect(body.perfilInvestidor).to.eq(null)
        expect(body.carteiraVinculada).to.eq(null)
      })

      comoAdmin()
      historico(conta.id).should('have.length', 0)
    })
  })

  it('SUI 07 · mesmas respostas enviadas duas vezes (retry após timeout) → uma só avaliação, mesmo perfil e vínculo estável (falha até haver idempotência)', () => {
    cy.criarUsuarioDescartavel().then((conta) => {
      cy.loginComo(conta)

      cy.avaliarSuitability(conta, 'maior').then((primeira) => {
        // Retry: o cliente não sabe se o primeiro envio valeu e repete exatamente o mesmo.
        cy.avaliarSuitability(conta, 'maior').then((segunda) => {
          expect(segunda.perfilResultante, 'sem troca de perfil silenciosa').to.eq(
            primeira.perfilResultante,
          )
          expect(segunda.pontuacaoTotal).to.eq(primeira.pontuacaoTotal)
          expect(segunda.carteiraRecomendada?.id, 'mesma carteira').to.eq(
            primeira.carteiraRecomendada?.id,
          )
        })

        cy.apiRequest<{ carteiraVinculada: { id: string } | null }>({
          method: 'GET',
          url: '/auth/me',
        })
          .its('body.carteiraVinculada.id')
          .should('eq', primeira.carteiraRecomendada?.id)

        comoAdmin()
        historico(conta.id).should('have.length', 1)
      })
    })
  })
})

export {}
